    windowEl=node('section','cx77-archive');windowEl.setAttribute('aria-label','开局档案库');
    const frame=node('div','archive-frame');frame.setAttribute('aria-hidden','true');
    frame.innerHTML='<svg viewBox="0 0 1000 600" preserveAspectRatio="none"><path class="archive-frame-rear" d="M18 5H974l25 25v550l-18 18H20"/><path d="M9 1H973l18 18v560l-15 15H16L1 579V9Z"/><path class="archive-frame-detail" d="M9 1h192m627 0h145l18 18v37M1 539v40l15 15h55M976 594l15-15v-34"/></svg>';
    const titlebar=node('header','archive-titlebar'),title=node('h3','','开局档案库'),brand=node('span','archive-brand','TOKYO 2051');title.prepend(icon('folder'));
    const controls=node('div','archive-window-controls');
    const expand=button('',()=>{expanded=!expanded;host.closest('.cxx-opening-flow').classList.toggle('archive-expanded',expanded);expand.setAttribute('aria-pressed',String(expanded));expand.setAttribute('aria-label',expanded?'还原档案窗口':'放大档案窗口');},'archive-window-button','expand');expand.setAttribute('aria-label','放大档案窗口');expand.setAttribute('aria-pressed','false');
    const close=button('',()=>flow.go('loadout'),'archive-window-button','close');close.setAttribute('aria-label','返回装备');close.hidden=!flow.canGo('loadout');
    controls.append(expand,close);titlebar.append(title,brand,controls);
    const grid=node('div','archive-grid');folders=node('nav','archive-folders');folders.setAttribute('aria-label','开局分类');
    const folderTitle=node('div','archive-folder-title','开局档案');folderTitle.prepend(icon('folder'));folders.append(folderTitle);
    categories.length=0;
    const addFolder=(id,label,nested=false)=>{const amount=id==='all'?records.length:records.filter(row=>row.group===id).length;const b=button('',()=>{category=id;showCatalog();renderList();},'archive-folder'+(nested?' archive-folder-child':''),'folder');b.append(node('span','',label),node('small','',String(amount)));b.dataset.category=id;categories.push(b);folders.append(b);};
    addFolder('all','全部');if(records.some(row=>row.group==='origin'))addFolder('origin','出身');
    folders.append(node('div','archive-folder-heading','乐队'));
    for(const band of groups.bands)addFolder(band.id,band.name,true);
    if(records.some(row=>row.group==='other'))addFolder('other','其他');
