    const files=node('section','archive-files'),toolbar=node('div','archive-toolbar'),searchLabel=node('label','archive-search');search=node('input','');search.type='search';search.placeholder='搜索开局…';search.setAttribute('aria-label','搜索开局、人物或地点');search.value=query;search.oninput=()=>{query=search.value;renderList();};searchLabel.append(icon('search'),search);
    const custom=button('自己写第一幕',()=>{mode='reading';flow.selectScenario('custom-opening');},'archive-custom','file');toolbar.append(searchLabel,custom);
    const listHead=node('div','archive-list-head');count=node('span','');listHead.append(node('span','','名称 / 分类'),count);
